// Flowise Custom Tool get_open_purchase_orders (generated by flowise/scinsight/build-scinsight.cjs)
// Read-only SAP purchase orders that are not yet received (supplier, material, quantity, promised date, confirmation status).
// SCInsight allowlisted tool: GET /api/v1/sap/purchase-orders (fixed endpoint; key from Flowise Variables, never from the model)
const fetch = require('node-fetch');
const base = String($vars.sci_api_url || '').replace(/\/+$/, '');
const key = String($vars.sci_agent_key || '');
if (!base || !key) return JSON.stringify({ error: 'configuration', detail: 'Flowise variables sci_api_url and sci_agent_key are required' });
const args = {};
let material_id = typeof $material_id === 'undefined' || $material_id === null ? '' : String($material_id).trim();
material_id = material_id.toUpperCase();
if (/^(none|null|undefined|n\/a)?$/i.test(material_id)) material_id = '';
if (material_id && !/^[A-Z0-9][A-Z0-9_-]{1,40}$/.test(material_id)) return JSON.stringify({ error: 'invalid_argument', detail: 'material_id has an invalid format: ' + material_id.slice(0, 40) });
if (material_id) args.material_id = material_id;
let supplier_id = typeof $supplier_id === 'undefined' || $supplier_id === null ? '' : String($supplier_id).trim();
supplier_id = supplier_id.toUpperCase();
if (/^(none|null|undefined|n\/a)?$/i.test(supplier_id)) supplier_id = '';
if (supplier_id && !/^[A-Z0-9][A-Z0-9_-]{1,40}$/.test(supplier_id)) return JSON.stringify({ error: 'invalid_argument', detail: 'supplier_id has an invalid format: ' + supplier_id.slice(0, 40) });
if (supplier_id) args.supplier_id = supplier_id;
let url = base + "/api/v1/sap/purchase-orders";
const qs = ["material_id","supplier_id"].filter((k) => args[k] !== undefined).map((k) => k + '=' + encodeURIComponent(args[k])).join('&');
if (qs) url += '?' + qs;
const options = { method: 'GET', headers: { 'X-API-Key': key, 'Content-Type': 'application/json', Accept: 'application/json' } };
let res;
try { res = await fetch(url, options); } catch (e) { return JSON.stringify({ error: 'unreachable', detail: String(e && e.message || e).slice(0, 200) }); }
const text = await res.text();
let data;
try { data = JSON.parse(text); } catch (e) { data = { detail: text.slice(0, 500) }; }
if (!res.ok) return JSON.stringify({ error: 'http_' + res.status, detail: data.detail || data });
if (Array.isArray(data.items)) data.items = data.items.filter((po) => !po.received_date);
// keep the answer inside the model context: drop record-level lineage, keep the snapshot id
const strip = (o) => Array.isArray(o) ? o.map(strip) : (o && typeof o === 'object') ? Object.fromEntries(Object.entries(o).filter(([k]) => k !== 'source_records' && k !== 'provenance').map(([k, v]) => [k, strip(v)])) : o;
const out = strip(data);
if (data && data.provenance) out.snapshot_id = data.provenance.snapshot_id;
const json = JSON.stringify(out);
return json.length > 9000 ? json.slice(0, 9000) + ' ...[truncated: call a narrower query]' : json;
